import SwiftUI
import RPMDesign

/// One genre's name in the same lettering as the desktop app, drawn from outlines (see
/// `GenreWordmarkTable`, generated by `scripts/gen_wordmarks.py`). It is scaled to fit the box it
/// is given, keeps its proportions, and sits on the bottom-left corner of the box.
public struct GenreLettering: View {
    let genre: String

    public init(genre: String) {
        self.genre = genre
    }

    public var body: some View {
        if let mark = GenreMarks.mark(genre) {
            LetteringShape(outline: Path(GenreMarks.outline(mark)))
                .fill(.white, style: FillStyle(eoFill: mark.evenOdd))
                .shadow(color: .black.opacity(0.35), radius: 6, y: 2)
                .accessibilityLabel(genre)
        } else {
            Text(genre)
                .font(SharedFaces.cabinBold.map { .custom($0, size: 28) } ?? .system(size: 28, weight: .bold))
                .foregroundStyle(.white)
                .lineLimit(1)
                .minimumScaleFactor(0.5)
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomLeading)
        }
    }
}

private struct LetteringShape: Shape {
    let outline: Path

    func path(in rect: CGRect) -> Path {
        let box = outline.cgPath.boundingBoxOfPath
        guard box.width > 0, box.height > 0 else { return Path() }

        let scale = min(rect.width / box.width, rect.height / box.height)
        let place = CGAffineTransform(translationX: rect.minX, y: rect.maxY - box.height * scale)
            .scaledBy(x: scale, y: scale)
            .translatedBy(x: -box.minX, y: -box.minY)
        return outline.applying(place)
    }
}

/// Each genre's lettering and colour, parsed once and cached.
@MainActor
public enum GenreMarks {
    private static let marks: [String: GenreWordmark] =
        Dictionary(GenreWordmarkTable.all.map { ($0.genre, $0) }, uniquingKeysWith: { first, _ in first })

    private static var outlines: [String: CGPath] = [:]

    public static func mark(_ genre: String) -> GenreWordmark? { marks[genre] }

    public static func outline(_ mark: GenreWordmark) -> CGPath {
        if let parsed = outlines[mark.genre] { return parsed }
        let parsed = VectorPath.parse(mark.path)
        outlines[mark.genre] = parsed
        return parsed
    }

    /// The genre's colour from the app palette, or nil for a genre with no lettering.
    public static func colour(_ genre: String) -> RGB? {
        guard let argb = marks[genre]?.colour else { return nil }
        return RGB(UInt8((argb >> 16) & 0xFF), UInt8((argb >> 8) & 0xFF), UInt8(argb & 0xFF))
    }
}
